        this.hotWordMapper = hotWordMapper;
        this.userMapper = userMapper;
    }

    public HotWord create(Long groupId, String text, Integer weight, String username) {
        User creator = userMapper.findByUsername(username);
        LocalDateTime now = LocalDateTime.now();
        HotWord hotWord = new HotWord(null, groupId, text, weight, creator.getId(), now, now);
        hotWordMapper.insert(hotWord);
        return hotWord;
    }

